<div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre v-pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> spaConfig <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token operator">...</span>routerConfig<span class="token punctuation">,</span></span>
<span class="line">  mode<span class="token operator">:</span> <span class="token string">'spa'</span> <span class="token keyword">as</span> <span class="token keyword">const</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="mpa-模式" tabindex="-1"><a class="header-anchor" href="#mpa-模式"><span>MPA 模式</span></a></h3>
