<span class="line">  router<span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    mode<span class="token operator">:</span> <span class="token string">'auto'</span> <span class="token keyword">as</span> <span class="token keyword">const</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token function-variable function">pagesFetcher</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=></span> <span class="token function">fetchPagesConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token function-variable function">userPermissionsProvider</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=></span> <span class="token function">getUserPermissions</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    appConfig<span class="token operator">:</span> <span class="token punctuation">{</span> </span>
<span class="line">      startPage<span class="token operator">:</span> <span class="token string">'home'</span><span class="token punctuation">,</span></span>
<span class="line">      defaultTransition<span class="token operator">:</span> <span class="token string">'slide'</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    animation<span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">      duration<span class="token operator">:</span> <span class="token number">300</span><span class="token punctuation">,</span></span>
<span class="line">      easing<span class="token operator">:</span> <span class="token string">'ease-in-out'</span><span class="token punctuation">,</span></span>
<span class="line">      enabled<span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">      type<span class="token operator">:</span> <span class="token string">'slide'</span> <span class="token keyword">as</span> <span class="token keyword">const</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  logger<span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    level<span class="token operator">:</span> <span class="token string">'info'</span> <span class="token keyword">as</span> <span class="token keyword">const</span><span class="token punctuation">,</span></span>
<span class="line">    transports<span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">      <span class="token keyword">new</span> <span class="token class-name">ConsoleTransport</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token keyword">new</span> <span class="token class-name">StorageTransport</span><span class="token punctuation">(</span><span class="token punctuation">{</span> maxEntries<span class="token operator">:</span> <span class="token number">2000</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    defaultContext<span class="token operator">:</span> <span class="token string">'MyApp'</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  appInfo<span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    appId<span class="token operator">:</span> <span class="token string">'wx123456'</span><span class="token punctuation">,</span></span>
<span class="line">    name<span class="token operator">:</span> <span class="token string">'My Application'</span><span class="token punctuation">,</span></span>
<span class="line">    version<span class="token operator">:</span> <span class="token string">'1.0.0'</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 使用完整配置初始化运行时</span></span>
<span class="line"><span class="token keyword">const</span> runtime <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">createRuntime</span><span class="token punctuation">(</span>completeKit<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre>
